css:
.employee-id-card {
  width: 400px;
  height: auto;
  padding: 20px;
  border: 2px solid #000;
  border-radius: 8px;
  font-size: 15px;
  font-family: 'Arial', sans-serif;
  box-sizing: border-box;
}

img {
        width: 350px;
}

.employee-id-card h3 {
  text-align: center;
  font-size: 20px;
  margin-bottom: 20px;
  text-transform: uppercase;
  padding-bottom: 5px;
}
  .title {
  text-align: center;
  font-size: 14px;
  margin-bottom: 5px;
  text-transform: uppercase;
  padding-bottom: 5px;
}

.employee-id-card .row {
  margin-bottom: 5px;
}

.employee-id-card .label {
  font-weight: bold;
  display: inline-block;
  text-align: left;

}

.employee-id-card .sign {
  font-style: italic;
  margin-top: 5px;
  padding-left: 10px;
}

.employee-id-card .note {
  margin-top: 15px;
  font-size: 14px;
  text-align: justify;
  border-top: 1px dashed #999;
  padding-top: 10px;
}

.employee-id-card .footer {
  margin-top: 10px;
  font-size: 14px;
  font-weight: bold;
  text-align: center;
}
